export function stepActor(state,elapsed,maxX,maxY,restitution){
 if(![state.x,state.y,state.vx,state.vy,elapsed,maxX,maxY,restitution].every(Number.isFinite)||maxX<0||maxY<0||restitution<0||restitution>1)throw Error('Invalid ecology motion');
 const s={...state},delta=Math.max(0,Math.min(32,elapsed))/16.67;
 s.vy+=.28*delta;s.vx*=Math.pow(.987,delta);s.vy*=Math.pow(.993,delta);s.x+=s.vx*delta;s.y+=s.vy*delta;
 if(s.x<=0||s.x>=maxX){s.x=Math.max(0,Math.min(maxX,s.x));s.vx*=-Math.max(.18,restitution)}
 if(s.y<=0){s.y=0;s.vy*= -.42}if(s.y>=maxY){s.y=maxY;s.vy*=-Math.max(.12,restitution);s.vx*=.86}
 s.moving=Math.abs(s.vx)+Math.abs(s.vy)>.32||s.y<maxY-1;if(!s.moving)s.vx=s.vy=0;return s;
}
