 function step(time){frame=0;if(!allowed()){halt();return}const dt=Math.max(0,Math.min(32,time-last));last=time;elapsed+=dt;for(const a of actors){if(a.moving&&!a.drag&&!a.pinned){Object.assign(a,stepActor(a,dt,...bounds(a),a.restitution));position(a)}}if(actors.some(a=>a.moving)&&elapsed<20000)frame=raf(step);else{halt();status.textContent=elapsed>=20000?'Motion paused at the 20-second simulation limit. Throw again explicitly.':'Objects settled. Saved layout unchanged.'}}
